namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
            new() { Id = 4, Name = "English", Abbreviation = "ENG" },
            new() { Id = 5, Name = "History", Abbreviation = "HIST" }
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, CourseCode = "CS101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", DepartmentId = 1, IsFeatured = true,
                InstructorName = "Dr. Sarah Chen",
                InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming. She holds a PhD from MIT and has published extensively on CS education."
            },
            new()
            {
                Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.",
                Credits = 4, Schedule = "Tue/Thu 10:30-11:50 AM", DepartmentId = 1, IsFeatured = true,
                InstructorName = "Dr. James Park",
                InstructorBio = "Dr. Park specializes in algorithm optimization and has contributed to several open-source projects. He joined the faculty in 2018."
            },
            new()
            {
                Id = 3, CourseCode = "CS301", Title = "Database Systems",
                Description = "Introduction to database design, SQL, normalization, transaction processing, and modern NoSQL systems.",
                Credits = 3, Schedule = "Mon/Wed 2:00-3:20 PM", DepartmentId = 1, IsFeatured = false,
                InstructorName = "Prof. Maria Garcia",
                InstructorBio = "Prof. Garcia worked in industry for 10 years at major tech companies before transitioning to academia. She specializes in distributed databases."
            },
            new()
            {
                Id = 4, CourseCode = "MATH101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", DepartmentId = 2, IsFeatured = true,
                InstructorName = "Dr. Robert Liu",
                InstructorBio = "Dr. Liu is an award-winning educator who has taught calculus for over 20 years. He is known for making complex topics accessible."
            },
            new()
            {
                Id = 5, CourseCode = "MATH201", Title = "Linear Algebra",
                Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.",
                Credits = 3, Schedule = "Tue/Thu 1:00-2:20 PM", DepartmentId = 2, IsFeatured = false,
                InstructorName = "Dr. Emily Watson",
                InstructorBio = "Dr. Watson's research focuses on applied linear algebra in machine learning. She holds dual appointments in Mathematics and Computer Science."
            },
            new()
            {
                Id = 6, CourseCode = "PHYS101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00-11:50 AM + Lab Thu 2:00-4:50 PM", DepartmentId = 3, IsFeatured = true,
                InstructorName = "Dr. Alan Foster",
                InstructorBio = "Dr. Foster is an experimental physicist whose research involves particle detection. He brings real-world lab experience to the classroom."
            },
            new()
            {
                Id = 7, CourseCode = "PHYS201", Title = "Electromagnetism",
                Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",
                Credits = 4, Schedule = "Tue/Thu 9:00-10:20 AM", DepartmentId = 3, IsFeatured = false,
                InstructorName = "Dr. Nina Patel",
                InstructorBio = "Dr. Patel is a theoretical physicist specializing in quantum electrodynamics. She has published over 50 peer-reviewed papers."
            },
            new()
            {
                Id = 8, CourseCode = "ENG101", Title = "English Composition",
                Description = "Develop critical reading and writing skills. Focus on argumentative essays, research papers, and rhetorical analysis.",
                Credits = 3, Schedule = "Mon/Wed 9:00-10:20 AM", DepartmentId = 4, IsFeatured = false,
                InstructorName = "Prof. David Kim",
                InstructorBio = "Prof. Kim is a published author and writing coach. He has helped thousands of students improve their academic writing."
            },
            new()
            {
                Id = 9, CourseCode = "ENG205", Title = "American Literature",
                Description = "Survey of major American literary works from the colonial period to the present. Emphasis on cultural and historical context.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM-12:20 PM", DepartmentId = 4, IsFeatured = false,
                InstructorName = "Dr. Rachel Adams",
                InstructorBio = "Dr. Adams specializes in 20th-century American fiction. Her book on the Harlem Renaissance received critical acclaim."
            },
            new()
            {
                Id = 10, CourseCode = "HIST101", Title = "World History to 1500",
                Description = "Survey of world civilizations from prehistory through the Renaissance. Covers political, social, and cultural developments.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00-1:50 PM", DepartmentId = 5, IsFeatured = false,
                InstructorName = "Dr. Thomas Brown",
                InstructorBio = "Dr. Brown is an archaeologist and historian who has led excavations in the Mediterranean. He brings artifacts and primary sources into the classroom."
            }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

